    public static bool TryGetIconId(EldenRingItem item, out int iconId) {
        iconId = 0;
        string name = NormalizeName(item.Name);
        if (IsArmorType(item.Type)) {
            if (ArmorByName.TryGetValue(name, out iconId) && iconId> 0) return true;
            string model = NormalizeModelId(item.ModelId);
            string key = model + "|" + item.Type;
            return ArmorByModelAndType.TryGetValue(key, out iconId) && iconId> 0;
        }
        if (string.Equals(item.Category, "Weapon", StringComparison.OrdinalIgnoreCase) || (!string.IsNullOrWhiteSpace(item.FileName) && item.FileName.StartsWith("wp_", StringComparison.OrdinalIgnoreCase))) {
            if (WeaponByName.TryGetValue(name, out iconId) && iconId> 0) return true;
            string model = NormalizeModelId(item.ModelId);
            return WeaponByModel.TryGetValue(model, out iconId) && iconId> 0;
        }
        return false;
    }
    private static string NormalizeName(string?value) {
        if (string.IsNullOrWhiteSpace(value)) return string.Empty;
        return string.Join(" ", value.Split((char[]?) null, StringSplitOptions.RemoveEmptyEntries)).Trim();
    }
    private static string NormalizeModelId(string?value) {
        if (int.TryParse(value, out int model)) return model.ToString();
        return value?.TrimStart('0') ?? string.Empty;
    }
    private static bool IsArmorType(string?type) {
        return string.Equals(type, "Helmet", StringComparison.OrdinalIgnoreCase) || string.Equals(type, "Chest Armor", StringComparison.OrdinalIgnoreCase) || string.Equals(type, "Gauntlet", StringComparison.OrdinalIgnoreCase) || string.Equals(type, "Greaves", StringComparison.OrdinalIgnoreCase);
    }
